"""Tiny text statistics helpers."""

import string


def word_count(text):
    """Number of whitespace-separated words in text."""
    return len(text.split())


def longest_word(text):
    """The longest word in text; empty string for empty input.

    Leading and trailing punctuation is ignored when comparing lengths, so
    "hello," loses to "goodbye" even though the raw tokens tie at 7 characters.
    The stripped form is what gets returned.
    """
    words = [word.strip(string.punctuation) for word in text.split()]
    if not words:
        return ""
    return max(words, key=len)


def char_frequencies(text):
    """Count each letter in text, lowercased; non-letters are ignored."""
    counts = {}
    for char in text.lower():
        if char.isalpha():
            counts[char] = counts.get(char, 0) + 1
    return counts

